function Set-KeevaultSetupLanguage {
    <#
    .SYNOPSIS
        Sprache der Texte, Schritte und Doku: de oder en. Ein Lauf merkt sich seine Sprache für die Doku.
    #>
    [CmdletBinding()]
    param([Parameter(Mandatory, Position = 0)][ValidateSet('de', 'en')][string] $Language)
    $script:KsLang = $Language
}

function KsT([string] $Key) {
    $entry = $script:KsText[$Key]
    if (-not $entry) { return $Key }
    $text = $entry[0]
    if ($script:KsLang -eq 'en') { $text = $entry[1] }
    if ($args.Count) { return ($text -f $args) }
    return $text
}
